/*
 * TrucAÍ — arte bitmap usada pelas cartas (Truco.CardArt), embutida como data: URI para funcionar
 * em file:// sem sujar o canvas (imagens de arquivo local bloqueariam o envio da textura à GPU).
 *   nous: logo da Nous Research (garota), pedida pelo usuário para a Dama de Copas.
 */
(function (root) {
  'use strict';
  const Truco = (root.Truco = root.Truco || {});
  Truco.CardArt = Object.freeze({
    nous: 'data:image/png;base64,',
  });
})(typeof window !== 'undefined' ? window : globalThis);
